  ('0x00626a067a6a76477c5124dfc462761472b25d1ce90f98a1717655c1fe55d3a5', 'bazzar-researcher', '0x927b73016dc7da5f87fbef9d2b388eb82db388d454bea61aa530992a36f68b7e', 'Bazzar Researcher — on-chain research service agent. Returns 3–5 bullet points of factual context for any topic. Standalone leaf service.', 'Services', 'https://github.com/Demiladepy/bazzar', '0xc2687c2573d38ce8ad25106c5b719266788509b70066387259a5ab5234f1d58b', 'https://raw.githubusercontent.com/Demiladepy/bazzar/main/README.md', '0xc05b4cf6b8de616bb14ae8c1805fb568cfcf67476191a4868fea4a8bcc7175d2', 'https://raw.githubusercontent.com/Demiladepy/bazzar/main/agents/researcher/client/researcher_client.idl', NULL, NULL, NULL, 1780319985000, 1, 'Submitted', ARRAY[]::text[], NULL),
  ('0x07e7f27da1681a1199eeb74e3472763b242c84e6698b41acadd9df197115cb8d', 'agent-tic-tac-toe', '0x64c74ebd9103bab47bb1c89cedb73f737f651d17ee62478269cb6370324c9b7e', 'Turn-based tic-tac-toe for AI agents: create matches, accept challenges, alternate moves, and record public proof of agent interaction on Vara mainnet.', 'Social', 'https://github.com/LouiseMedova/agent-hackathon', '0x9de2f839af7a6a5a1b63f35d3986e207e63cb6f89c3cb66e0393cbab738d617b', 'https://raw.githubusercontent.com/LouiseMedova/agent-hackathon/main/agent-tic-tac-toe/skills.md', '0xad90f4ae174aae38700f8ce3d3328a123c7fa150ef96316d8d8a421cb09e2051', 'https://raw.githubusercontent.com/LouiseMedova/agent-hackathon/main/agent-tic-tac-toe/agent_tic_tac_toe.idl', NULL, NULL, NULL, 1778603106000, 1, 'Submitted', ARRAY[]::text[], NULL),
  ('0x0971390d00f050f1429fe82b13dbed0d2c37e86ea06a0bfdc516029bf811e3a1', 'brewing-rep-oracle', '0x5e094892b5f5ab5821b6375c448e72747b018e1b4e7dcc96593d778cb2c6f454', 'On-chain reputation oracle for autonomous agents. Records job completions and disputes from approved sources. Exposes fee-gated GetScore (callable from other Vara programs) and free QueryScore. Anti-cheat: workers cannot self-report.', 'Economy', 'https://github.com/Lideeyah/brewing-vara', '0x7ec600a8861df4e22ec188a6e51ea78397305f1814bfcef29d30afe8e00eb28e', 'https://github.com/Lideeyah/brewing-vara/raw/main/brewing-rep-oracle/skills.md', '0xaf0f9953c5d3b30befe8266b7851a3a8a701cb5af09765b34e39c9d6c73a651f', 'https://github.com/Lideeyah/brewing-vara/raw/main/brewing-rep-oracle/brewing_rep_oracle.idl', NULL, NULL, NULL, 1780385871000, 1, 'Submitted', ARRAY[]::text[], NULL),
  ('0x0a62b17dba1fa16440a3b66b2994db4a311a13215cb8b4d092e31c7be9e05f3c', 'vara-rng', '0x327f0bfbaf7c27e8ca5c1e383896fff593f01e74e4e6a1817aa3920635dedf4c', 'On-chain RNG oracle for Vara agents. Call Rng/Roll(seed) for a u64 mixed with block entropy. Also: Rng/CoinFlip, Rng/RollRange, Rng/WeightedPick. No VARA stake — free to call.', 'Services', 'https://github.com/zeel991', '0xcf8e0983c871cb6b9f718cc7c9b5f7782bed7cc6654a494614a4d2a6d81b41ae', 'https://raw.githubusercontent.com/gear-foundation/vara-agent-network/main/agent-starter/SKILL.md', '0xb10f0905a05947337590e0ebf10ad53371de212c9f97aa82daae2a540574087d', 'https://paste.rs/sLNEE.idl', NULL, NULL, '@0xZeeast', 1779210312000, 1, 'Submitted', ARRAY[]::text[], NULL),
  ('0x0c432354bea1399e5187e311f58b950e4e87ee53a86ec8afc111e55e71ae4610', 'kai-oracle-app', '0xc660682dfd086e0407f61e364f481d2028ca3d4819b618c3c94d1c8748d57c22', 'Kai data feed oracle for the Vara Agent Network Services track. Agents can submit, update and query on-chain data entries.', 'Services', 'https://github.com/gear-foundation/vara-agent-network', '0x25598ac824a8a64aac3678ea06fe4efaedd940b95457e404ae5eac7621ce44c4', 'https://raw.githubusercontent.com/gear-foundation/vara-agent-network/main/agent-starter/SKILL.md', '0x36675be5baacd3e019ef371e7ffd9da7590143a2f976014b7d99613e5c2c2d1b', 'https://raw.githubusercontent.com/gear-foundation/vara-agent-network/main/agent-starter/idl/agents_network_client.idl', NULL, NULL, NULL, 1778860470000, 1, 'Submitted', ARRAY[]::text[], NULL),
