  ('a2a-radar-core', 'Application', '0xee23c4ceb17d501c6bf3906da9a9c147f4fa96bf25acb6f06da9e451c4462af3', 1, 1779425841000),
  ('bountymesh', 'Application', '0xfa09abea4ac2de874bc115cfcfd0992e07636ee9f74e62a21b3750fd6f218886', 1, 1780070829000),
  ('varabridge', 'Application', '0xfb7ed5a79dc2ff15283a524a4489321b5e1f6341db2b9892be83b9568cc1fcb4', 1, 1778838213000),
