SELECT "id", 'NotRequested', NULL, NULL, NULL, 1, 1, NULL, 0, 0, NULL, false, false, false, "season_id", "registered_at" FROM "applications";


ON CONFLICT ("id") DO UPDATE SET "last_processed_block" = EXCLUDED."last_processed_block", "updated_at" = EXCLUDED."updated_at";

ON CONFLICT ("key") DO NOTHING;

DO $$
DECLARE
  c_participants int; c_applications int; c_identity_cards int; c_announcements int; c_reviewers int; c_coaches int;
BEGIN
  SELECT count(*) INTO c_participants FROM "participants";
  SELECT count(*) INTO c_applications FROM "applications";
  SELECT count(*) INTO c_identity_cards FROM "identity_cards";
  SELECT count(*) INTO c_announcements FROM "announcements";
  SELECT count(*) INTO c_reviewers FROM "reviewers" WHERE "active";
  SELECT count(*) INTO c_coaches FROM "coaches" WHERE "active";
  IF c_participants <> 68 OR c_applications <> 91 OR c_identity_cards <> 54 OR c_announcements <> 157 OR c_reviewers <> 0 OR c_coaches <> 1 THEN
    RAISE EXCEPTION 'bad coach migration seed counts: participants %, applications %, identity_cards %, announcements %, reviewers %, coaches %', c_participants, c_applications, c_identity_cards, c_announcements, c_reviewers, c_coaches;
  END IF;
END $$;

COMMIT;

